input.command:
cat > /tmp/kingdee_presentation.html << 'EOF'
<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>金蝶国际2025年度财务分析报告</title>
    <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: 'Microsoft YaHei', 'PingFang SC', 'Helvetica Neue', Arial, sans-serif;
            line-height: 1.6;
            color: #333;
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            min-height: 100vh;
        }

        .container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 20px;
        }

        .header {
            background: rgba(255, 255, 255, 0.95);
            backdrop-filter: blur(10px);
            border-radius: 20px;
            padding: 40px;
            margin-bottom: 30px;
            text-align: center;
            box-shadow: 0 20px 40px rgba(0, 0, 0, 0.1);
        }

        .header h1 {
            color: #2c3e50;
            font-size: 2.5em;
            margin-bottom: 10px;
            font-weight: 700;
        }

        .header .subtitle {
            color: #7f8c8d;
            font-size: 1.2em;
            margin-bottom: 20px;
        }

        .header .stock-info {
            display: inline-block;
            background: #3498db;
            color: white;
            padding: 10px 20px;
            border-radius: 25px;
            font-weight: 600;
        }

        .section {
            background: rgba(255, 255, 255, 0.95);
            backdrop-filter: blur(10px);
            border-radius: 20px;
            padding: 30px;
            margin-bottom: 30px;
            box-shadow: 0 15px 35px rgba(0, 0, 0, 0.1);
        }

        .section h2 {
            color: #2c3e50;
            font-size: 1.8em;
            margin-bottom: 20px;
            border-bottom: 3px solid #3498db;
            padding-bottom: 10px;
        }

        .section h3 {
            color: #34495e;
            font-size: 1.4em;
            margin: 20px 0 15px 0;
        }

        .metrics-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 20px;
            margin: 20px 0;
        }

        .metric-card {
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            color: white;
            padding: 25px;
            border-radius: 15px;
            text-align: center;
            box-shadow: 0 10px 25px rgba(0, 0, 0, 0.15);
            transition: transform 0.3s ease;
        }

        .metric-card:hover {
            transform: translateY(-5px);
        }

        .metric-value {
            font-size: 2.2em;
            font-weight: 700;
            margin-bottom: 5px;
        }

        .metric-label {
            font-size: 1em;
            opacity: 0.9;
        }

        .metric-change {
            font-size: 0.9em;
            margin-top: 5px;
            padding: 5px 10px;
            background: rgba(255, 255, 255, 0.2);
            border-radius: 10px;
            display: inline-block;
        }

        .chart-container {
            position: relative;
            height: 400px;
            margin: 20px 0;
            background: white;
            border-radius: 15px;
            padding: 20px;
            box-shadow: 0 5px 15px rgba(0, 0, 0, 0.1);
        }

        .data-table {
            width: 100%;
            border-collapse: collapse;
            margin: 20px 0;
            background: white;
            border-radius: 10px;
            overflow: hidden;
            box-shadow: 0 5px 15px rgba(0, 0, 0, 0.1);
        }

        .data-table th {
            background: #3498db;
            color: white;
            padding: 15px;
            text-align: left;
            font-weight: 600;
        }

        .data-table td {
            padding: 12px 15px;
            border-bottom: 1px solid #ecf0f1;
        }

        .data-table tr:hover {
            background: #f8f9fa;
        }

        .highlight-box {
            background: linear-gradient(135deg, #f093fb 0%, #f5576c 100%);
            color: white;
            padding: 20px;
            border-radius: 15px;
            margin: 20px 0;
        }

        .highlight-box h4 {
            margin-bottom: 10px;
            font-size: 1.3em;
        }

        .risk-indicator {
            display: inline-block;
            padding: 5px 15px;
            border-radius: 20px;
            font-size: 0.9em;
            font-weight: 600;
        }

        .risk-low { background: #2ecc71; color: white; }
        .risk-medium { background: #f39c12; color: white; }
        .risk-high { background: #e74c3c; color: white; }

        .recommendation {
            background: linear-gradient(135deg, #11998e 0%, #38ef7d 100%);
            color: white;
            padding: 25px;
            border-radius: 15px;
            margin: 20px 0;
            text-align: center;
        }

        .recommendation h3 {
            margin-bottom: 15px;
            font-size: 1.5em;
        }

        .footer {
            text-align: center;
            padding: 20px;
            color: rgba(255, 255, 255, 0.8);
            font-size: 0.9em;
        }

        @media (max-width: 768px) {
            .container {
                padding: 10px;
            }

            .header h1 {
                font-size: 2em;
            }

            .metrics-grid {
                grid-template-columns: 1fr;
            }

            .chart-container {
                height: 300px;
            }
        }
    </style>
</head>
<body>
    <div class="container">
        <!-- 头部 -->
        <div class="header">
            <h1>金蝶国际2025年度财务分析报告</h1>
            <div class="subtitle">Kingdee International Software Group Limited</div>
            <div class="stock-info">股票代码: 268.HK</div>
        </div>

        <!-- 执行摘要 -->
        <div class="section">
            <h2>📊 执行摘要</h2>
            <div class="highlight-box">
                <h4>核心成就</h4>
                <p>金蝶国际2025年度成功实现扭亏为盈，总收入达到70.06亿元，同比增长12.0%。云服务业务占比提升至82.5%，数字化转型战略成效显著，AI应用商业化加速推进。</p>
            </div>

            <div class="metrics-grid">
                <div class="metric-card">
                    <div class="metric-value">70.06亿</div>
                    <div class="metric-label">总收入</div>
                    <div class="metric-change">+12.0%</div>
                </div>
                <div class="metric-card">
                    <div class="metric-value">0.93亿</div>
                    <div class="metric-label">净利润</div>
                    <div class="metric-change">扭亏为盈</div>
                </div>
                <div class="metric-card">
                    <div class="metric-value">10.97亿</div>
                    <div class="metric-label">经营现金流</div>
                    <div class="metric-change">+17.6%</div>
                </div>
                <div class="metric-card">
                    <div class="metric-value">82.5%</div>
                    <div class="metric-label">云服务占比</div>
                    <div class="metric-change">持续提升</div>
                </div>
            </div>
        </div>

        <!-- 收入结构分析 -->
        <div class="section">
            <h2>💰 收入结构分析</h2>
            <div class="chart-container">
                <canvas id="revenueChart"></canvas>
            </div>

            <table class="data-table">
                <thead>
                    <tr>
                        <th>业务板块</th>
                        <th>收入（亿元）</th>
                        <th>占比</th>
                        <th>同比增长</th>
                    </tr>
                </thead>
                <tbody>
                    <tr>
                        <td>云服务</td>
                        <td>57.82</td>
                        <td>82.5%</td>
                        <td>-</td>
                    </tr>
                    <tr>
                        <td>订阅服务</td>
                        <td>35.56</td>
                        <td>50.8%</td>
                        <td>+20.9%</td>
                    </tr>
                    <tr>
                        <td>苍穹与星瀚</td>
                        <td>19.4</td>
                        <td>27.7%</td>
                        <td>+28.0%</td>
                    </tr>
                    <tr>
                        <td>其他业务</td>
                        <td>12.24</td>
                        <td>17.5%</td>
                        <td>-</td>
                    </tr>
                </tbody>
            </table>
        </div>

        <!-- 盈利能力分析 -->
        <div class="section">
            <h2>📈 盈利能力分析</h2>
            <div class="chart-container">
                <canvas id="profitChart"></canvas>
            </div>

            <div class="metrics-grid">
                <div class="metric-card">
                    <div class="metric-value">67.1%</div>
                    <div class="metric-label">毛利率</div>
                    <div class="metric-change">保持高位</div>
                </div>
                <div class="metric-card">
                    <div class="metric-value">3.3%</div>
                    <div class="metric-label">经调整净利率</div>
                    <div class="metric-change">显著改善</div>
                </div>
                <div class="metric-card">
                    <div class="metric-value">40.9亿</div>
                    <div class="metric-label">ARR</div>
                    <div class="metric-change">稳定增长</div>
                </div>
                <div class="metric-card">
                    <div class="metric-value">37.73亿</div>
                    <div class="metric-label">合同负债</div>
                    <div class="metric-change">未来保障</div>
                </div>
            </div>
        </div>

        <!-- 业务亮点 -->
        <div class="section">
            <h2>🚀 业务亮点</h2>
            <div class="metrics-grid">
                <div class="metric-card">
                    <div class="metric-value">1,461</div>
                    <div class="metric-label">新签大型企业</div>
                    <div class="metric-change">专精特新</div>
                </div>
                <div class="metric-card">
                    <div class="metric-value">463</div>
                    <div class="metric-label">新签海外企业</div>
                    <div class="metric-change">国际化</div>
                </div>
                <div class="metric-card">
                    <div class="metric-value">3.56亿</div>
                    <div class="metric-label">AI合同签约</div>
                    <div class="metric-change">商业化加速</div>
                </div>
                <div class="metric-card">
                    <div class="metric-value">740万+</div>
                    <div class="metric-label">企业客户</div>
                    <div class="metric-change">稳固基础</div>
                </div>
            </div>
        </div>

        <!-- 风险评估 -->
        <div class="section">
            <h2>⚠️ 风险评估</h2>
            <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 20px;">
                <div>
                    <h3>财务风险</h3>
                    <span class="risk-indicator risk-medium">中等风险</span>
                    <p style="margin-top: 10px;">净利润率仍然较低，盈利能力有待进一步提升</p>
                </div>
                <div>
                    <h3>经营风险</h3>
                    <span class="risk-indicator risk-medium">中等风险</span>
                    <p style="margin-top: 10px;">市场竞争加剧，需要持续投入研发保持技术领先</p>
                </div>
                <div>
                    <h3>市场风险</h3>
                    <span class="risk-indicator risk-low">低风险</span>
                    <p style="margin-top: 10px;">数字化转型大趋势支撑，宏观经济影响可控</p>
                </div>
            </div>
        </div>

        <!-- 投资建议 -->
        <div class="section">
            <div class="recommendation">
                <h3>🎯 投资建议</h3>
                <div style="font-size: 1.8em; font-weight: 700; margin: 15px 0;">推荐评级: 买入</div>
                <p>基于云服务转型成功、AI应用商业化加速、财务表现显著改善等因素，金蝶国际在企业数字化转型大趋势下具有良好的长期投资价值。</p>
            </div>
        </div>

        <!-- 未来展望 -->
        <div class="section">
            <h2>🔮 未来展望</h2>
            <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 20px;">
                <div class="highlight-box">
                    <h4>AI应用深化</h4>
                    <p>AI技术将进一步融入产品，提升客户价值和竞争优势</p>
                </div>
                <div class="highlight-box">
                    <h4>国际化加速</h4>
                    <p>海外市场拓展将成为新的增长点，全球化布局</p>
                </div>
                <div class="highlight-box">
                    <h4>生态建设</h4>
                    <p>平台化战略将构建更完整的企业服务生态</p>
                </div>
                <div class="highlight-box">
                    <h4>行业深耕</h4>
                    <p>垂直行业解决方案将带来新的增长机会</p>
                </div>
            </div>
        </div>
    </div>

    <div class="footer">
        <p>本报告基于公开财务数据编制，仅供参考 | 报告日期：2026年5月16日</p>
    </div>

    <script>
        // 收入结构图表
        const revenueCtx = document.getElementById('revenueChart').getContext('2d');
        new Chart(revenueCtx, {
            type: 'doughnut',
            data: {
                labels: ['云服务', '其他业务'],
                datasets: [{
                    data: [57.82, 12.24],
                    backgroundColor: ['#3498db', '#95a5a6'],
                    borderWidth: 0
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                    title: {
                        display: true,
                        text: '2025年收入结构分布',
                        font: { size: 16, weight: 'bold' }
                    },
                    legend: {
                        position: 'bottom'
                    }
                }
            }
        });

        // 盈利能力图表
        const profitCtx = document.getElementById('profitChart').getContext('2d');
        new Chart(profitCtx, {
            type: 'bar',
            data: {
                labels: ['总收入', '云服务收入', '订阅收入', '经营现金流'],
                datasets: [{
                    label: '金额（亿元）',
                    data: [70.06, 57.82, 35.56, 10.97],
                    backgroundColor: ['#3498db', '#2ecc71', '#f39c12', '#9b59b6'],
                    borderRadius: 8
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                    title: {
                        display: true,
                        text: '2025年关键财务指标',
                        font: { size: 16, weight: 'bold' }
                    }
                },
                scales: {
                    y: {
                        beginAtZero: true,
                        title: {
                            display: true,
                            text: '金额（亿元）'
                        }
                    }
                }
            }
        });
    </script>
</body>
</html>
EOF
